import React, { useState, useEffect } from 'react';
import { getAllExamCounts } from '../services/api';  // Import the getAllExamCounts function

const ExamDataCount = ({ franchiseId }) => {
    const [examDataCount, setExamDataCount] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Function to fetch exam data count using getAllExamCounts
    const fetchExamDataCount = async () => {
        setLoading(true);
        setError('');
        try {
            const response = await getAllExamCounts(franchiseId);
            setExamDataCount(response);  // Assuming the response is the data containing the counts
        } catch (err) {
            console.error(err);
            setError('An error occurred while fetching data.');
        } finally {
            setLoading(false);
        }
    };

    // Fetch data on component mount
    useEffect(() => {
        fetchExamDataCount();
    }, [franchiseId]);

    return (
        <div>
            <h2>Exam Data Count for Franchise {franchiseId}</h2>

            <button onClick={fetchExamDataCount} disabled={loading}>
                {loading ? 'Loading...' : 'Refresh Exam Data Count'}
            </button>

            {error && <p style={{ color: 'red' }}>{error}</p>}

            {examDataCount !== null && !loading && (
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '20px' }}>
                    {/* Box for Exams Today */}
                    <div style={{ width: '30%', padding: '20px', border: '1px solid #ccc', borderRadius: '8px', textAlign: 'center' }}>
                        <h3>Exams Today</h3>
                        <p>{examDataCount.examsByDay !== undefined ? examDataCount.examsByDay : 'No data'}</p>
                    </div>

                    {/* Box for Exams This Week */}
                    <div style={{ width: '30%', padding: '20px', border: '1px solid #ccc', borderRadius: '8px', textAlign: 'center' }}>
                        <h3>Exams This Week</h3>
                        <p>{examDataCount.examsByWeek !== undefined ? examDataCount.examsByWeek : 'No data'}</p>
                    </div>

                    {/* Box for Exams This Month */}
                    <div style={{ width: '30%', padding: '20px', border: '1px solid #ccc', borderRadius: '8px', textAlign: 'center' }}>
                        <h3>Exams This Month</h3>
                        <p>{examDataCount.examsByMonth !== undefined ? examDataCount.examsByMonth : 'No data'}</p>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ExamDataCount;
